+fn rejected_call_result_is_replayed_after_reload() {
+    let fixture = Fixture::new();
+    let journal = SessionJournal::open(fixture.path()).unwrap();
+    fixture.run(&journal, ScriptedModel::new([oversized_create_call("call-1")]));
+    let second = ScriptedModel::new([text_reply("done")]);
+    fixture.run(&journal, second.clone());
+    let history = second.requests()[0].history();
+    assert_eq!(history.tool_results(), ["call-1: argument_size"]);
+    let reopened = SessionJournal::open(fixture.path()).unwrap();
+    assert_eq!(reopened.events().len(), 4);
